def to_int(s):
    try:
        return int(s)
    except ValueError:
        return -1

print(to_int('42'))
print(to_int('abc'))
print(to_int('3.14'))

def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

print(safe_div(10, 3))
print(safe_div(10, 0))

